@Test void cssSelectorParentWithId() {
    // https://github.com/jhy/jsoup/issues/2282
    Document doc = Jsoup.parse("<div><div id=id1><p>A</p></div><div><p>B</p></div><div class='c1 c2'><p>C</p></div></div>");
