import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import java.util.*;

public class Fuzz {
    static int fails = 0;
    static int checked = 0;

    static void check(Document doc, String label) {
        String before = doc.html();
        List<Element> els = doc.select("*");
        for (Element el : els) {
            String sel;
            try { sel = el.cssSelector(); }
            catch (Exception e) { fail(label, el, "cssSelector threw: " + e, null); continue; }
            String sel2 = el.cssSelector();
            if (!sel.equals(sel2)) { fail(label, el, "non-deterministic: " + sel + " vs " + sel2, sel); continue; }
            Elements found;
            try { found = doc.select(sel); }
            catch (Exception e) { fail(label, el, "select threw for '" + sel + "': " + e, sel); continue; }
            if (found.size() != 1 || found.get(0) != el) {
                fail(label, el, "matched " + found.size() + " with " + sel, sel);
                continue;
            }
            // round trip
            Document doc2 = Jsoup.parse(doc.html());
            Elements found2;
            try { found2 = doc2.select(sel); }
            catch (Exception e) { fail(label, el, "roundtrip select threw for '" + sel + "': " + e, sel); continue; }
            if (found2.size() != 1) { fail(label, el, "roundtrip matched " + found2.size() + " with " + sel, sel); continue; }
            checked++;
        }
        if (!before.equals(doc.html())) {
            System.out.println("!! DOM MUTATED in " + label);
            fails++;
        }
    }

    static void fail(String label, Element el, String msg, String sel) {
        fails++;
        if (fails <= 60)
            System.out.println("FAIL [" + label + "] " + describe(el) + " :: " + msg);
    }

    static String describe(Element el) {
        return "<" + el.tagName() + " id='" + el.id() + "' class='" + el.className() + "'>";
    }

    public static void main(String[] args) {
        String[] specials = {"a", "a b", "a.b", "a#b", "a:b", "a[b", "a]b", "a(b", "a)b", "a*b",
            "a\\b", "1abc", "-1abc", "-", "a'b", "a\"b", "café", "日本語", "a,b", "a>b", "a+b", "a~b",
            "a b.c d", "a;b", "a/b", "a=b", "a\nb", "a\tb", "[", "]", "()", "*", ":", "#", ".",
            "a%b", "a@b", "a!b", "a?b", "a&b", "a^b", "a$b", "a|b", "a{b", "a}b", "a<b", "👨x", "é"};
        String[] tags = {"div", "p", "span", "ul", "ol", "li", "table", "tr", "td", "tbody", "thead",
            "picture", "source", "img", "article", "section", "a", "b", "i", "h1", "dt", "dd", "html", "body",
            "fb:comments", "my-elem", "custom.tag"};

        // 1. pairwise: siblings sharing tricky classes/ids
        for (String t1 : tags) {
            for (String c1 : specials) {
                String html = "<" + t1 + " class='" + c1.replace("'", "&apos;") + "'><p>x</p></" + t1 + ">"
                    + "<" + t1 + " class='" + c1.replace("'", "&apos;") + "'><p>y</p></" + t1 + ">";
                Document doc = Jsoup.parse(html);
                check(doc, "pairclass " + t1 + " / " + c1);
            }
        }
        // 2. duplicate ids with specials
        for (String id : specials) {
            String html = "<div id='" + id.replace("'", "&apos;") + "'>a</div><div id='" + id.replace("'", "&apos;") + "'>b</div>";
            check(Jsoup.parse(html), "dupid " + id);
        }
        // 3. random fuzz
        Random rnd = new Random(42);
        for (int iter = 0; iter < 3000; iter++) {
            StringBuilder sb = new StringBuilder();
            buildRandom(sb, rnd, 0, tags, specials, rnd.nextInt(4)+2);
            Document doc;
            try { doc = Jsoup.parse(sb.toString()); } catch (Exception e) { continue; }
            check(doc, "fuzz" + iter);
        }
        // 4. specific structural cases
        String[] docs = {
            "<picture><source srcset='a'><img src='a' alt=''></picture><picture><source srcset='b'><img src='b'></picture>",
            "<table><tr><td>1</td><td>2</td></tr><tr><td>3</td><td>4</td></tr></table>",
            "<ul><li>a<ul><li>a1</li><li>a2</li></ul></li><li>b</li></ul>",
            "<div><div></div></div><div><div></div></div>",
            "<p>text<span>s1</span>mid<span>s2</span></p>",
            "<html><head></head><body><div></div></body></html>",
            "<div id='x'><div id='x'></div></div>",
            "<a-b class='a-b'><a-b></a-b></a-b><a-b class='a-b'></a-b>",
        };
        for (String h : docs) check(Jsoup.parse(h), "struct");

        System.out.println("checked=" + checked + " fails=" + fails);
        if (fails > 0) System.exit(1);
    }

    static void buildRandom(StringBuilder sb, Random rnd, int depth, String[] tags, String[] specials, int maxDepth) {
        String tag = tags[rnd.nextInt(tags.length)];
        sb.append("<").append(tag);
