import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import java.util.*;

public class FuzzValid {
    static int fails = 0, checked = 0, inDocFails = 0, rtFails = 0, detFails = 0;
    static List<String> samples = new ArrayList<>();

    static void record(String kind, String s) {
        fails++;
        if (samples.size() < 80) samples.add(kind + ": " + s);
    }

    static void check(Document doc, String label) {
        List<Element> els = doc.select("*");
        for (Element el : els) {
            String sel, sel2;
            try { sel = el.cssSelector(); sel2 = el.cssSelector(); }
            catch (Exception e) { record("throw", label + " " + desc(el) + " :: " + e); continue; }
            if (!sel.equals(sel2)) { detFails++; record("nondet", label + " " + desc(el)); continue; }
            Elements found;
            try { found = doc.select(sel); }
            catch (Exception e) { inDocFails++; record("select-threw", label + " " + desc(el) + " :: " + sel + " :: " + e); continue; }
            if (found.size() != 1 || found.get(0) != el) {
                inDocFails++; record("in-doc", label + " " + desc(el) + " matched=" + found.size() + " :: " + visible(sel));
                continue;
            }
            // roundtrip
            String html = doc.html();
            Document doc2 = Jsoup.parse(html);
            Elements found2;
            try { found2 = doc2.select(sel); }
            catch (Exception e) { rtFails++; record("rt-threw", label + " " + desc(el) + " :: " + visible(sel) + " :: " + e); continue; }
            if (found2.size() != 1) {
                rtFails++; record("rt-count", label + " " + desc(el) + " matched=" + found2.size() + " :: " + visible(sel));
                continue;
            }
            // structural position must match
            if (!path(found2.first()).equals(path(el))) {
                rtFails++; record("rt-pos", label + " want=" + path(el) + " got=" + path(found2.first()) + " :: " + visible(sel));
                continue;
            }
            checked++;
        }
    }

    static String path(Element e) {
        StringBuilder sb = new StringBuilder();
        Node n = e;
        while (n instanceof Element) {
            Element el = (Element) n;
            sb.insert(0, "/" + el.tagName() + "[" + el.elementSiblingIndex() + "]");
            n = el.parentNode();
        }
        return sb.toString();
    }
    static String visible(String s) { return s.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r"); }
    static String desc(Element el) { return "<" + el.tagName() + " id=[" + visible(el.id()) + "] class=[" + visible(el.className()) + "]>"; }

    static final String[] SPECIALS = {"a", "a b", "a.b", "a#b", "a:b", "a[b]", "a(b)", "a*b",
        "a\\b", "1abc", "-1abc", "-", "a'b", "a\"b", "café", "日本語", "a,b", "a>b", "a+b", "a~b",
        "a;b", "a/b", "a=b", "a\nb", "a\tb", ":", "#", ".", "a%b", "a@b", "a!b", "a?b", "a&b",
        "a^b", "a$b", "a|b", "a{b}", "👨x", "é", " ", "  ", "a  b", "-", "--", "x-y_z"};

    static final Random rnd = new Random(7);

    // valid-nesting builder
    static void build(StringBuilder sb, String parent, int depth) {
        int choice = rnd.nextInt(10);
        String tag;
        boolean leaf = false;
        if (depth > 5) choice = 9;
        switch (choice) {
            case 0: tag = "section"; break;
            case 1: tag = "article"; break;
            case 2: tag = "div"; break;
            case 3: tag = "p"; leaf = true; break;
            case 4: tag = "span"; leaf = true; break;
            case 5: tag = "ul"; openList(sb, "ul"); return;
            case 6: tag = "ol"; openList(sb, "ol"); return;
            case 7: tag = "table"; openTable(sb); return;
            case 8: tag = "picture"; openPicture(sb); return;
            default: tag = "a"; leaf = true;
        }
        open(sb, tag);
        if (!leaf) {
            int kids = rnd.nextInt(4);
            for (int i=0;i<kids;i++) build(sb, tag, depth+1);
            sb.append("text");
        } else sb.append("t");
        close(sb, tag);
        if (rnd.nextBoolean()) build(sb, parent, depth); // sibling
    }

    static void openList(StringBuilder sb, String tag) {
        open(sb, tag);
        int n = rnd.nextInt(4)+1;
        for (int i=0;i<n;i++) {
            open(sb, "li");
            if (rnd.nextBoolean()) build(sb, "li", 6);
            if (rnd.nextInt(3)==0) openList(sb, rnd.nextBoolean()?"ul":"ol"); // nested list inside li is valid
            sb.append("item").append(i);
            close(sb, "li");
        }
        close(sb, tag);
    }
    static void openTable(StringBuilder sb) {
        open(sb, "table");
        if (rnd.nextBoolean()) { open(sb,"thead"); row(sb); close(sb,"thead"); }
        open(sb, "tbody");
        int rows = rnd.nextInt(3)+1;
        for (int r=0;r<rows;r++) row(sb);
        close(sb, "tbody");
        close(sb, "table");
    }
    static void row(StringBuilder sb) {
        open(sb,"tr");
        int cells = rnd.nextInt(3)+1;
        for (int c=0;c<cells;c++){ open(sb,"td"); if(rnd.nextBoolean()) build(sb,"td",6); sb.append(c); close(sb,"td"); }
        close(sb,"tr");
    }
    static void openPicture(StringBuilder sb) {
        open(sb, "picture");
        if (rnd.nextBoolean()) { open(sb,"source"); sb.append(" srcset='x' "); close(sb,"source"); }
        open(sb,"img"); sb.append(" src='x' alt='x' "); close(sb,"img");
        close(sb, "picture");
    }

    static void open(StringBuilder sb, String tag) {
        sb.append("<").append(tag);
        if (rnd.nextInt(3) != 0) {
            String id = SPECIALS[rnd.nextInt(SPECIALS.length)];
            sb.append(" id='").append(attr(id)).append("'");
        }
        if (rnd.nextInt(2)==0) {
            int n = rnd.nextInt(3);
            if (n>0) {
                sb.append(" class='");
                for (int i=0;i<n;i++){ if(i>0) sb.append(' '); sb.append(attr(SPECIALS[rnd.nextInt(SPECIALS.length)])); }
                sb.append("'");
            }
        }
        sb.append(">");
    }
    static String attr(String s){ return s.replace("&","&amp;").replace("'","&apos;").replace("\"","&quot;").replace("<","&lt;"); }
    static void close(StringBuilder sb, String tag){ sb.append("</").append(tag).append(">"); }

    public static void main(String[] args) {
        // fixed structural docs
        String[] fixed = {
            "<picture><source srcset='a'><img src='a' alt=''></picture><picture><source srcset='b'><img src='b'></picture>",
            "<table><thead><tr><th>h</th></tr></thead><tbody><tr><td>1</td><td>2</td></tr><tr><td>3</td><td>4</td></tr></tbody></table>",
            "<ul><li>a<ul><li>a1</li><li>a2<ul><li>z</li></ul></li></ul></li><li>b</li></ul>",
            "<div><div></div></div><div><div></div></div>",
            "<p>text<span>s1</span>mid<span>s2</span>tail</p>",
            "<div id='x'><div id='x'></div></div>",
            "<body><div>b</div></body>",
            "<html><head><title>t</title></head><body></body></html>",
            "<dl><dt>t</dt><dd>d</dd><dt>t2</dt><dd>d2</dd></dl>",
        };
        for (String h : fixed) check(Jsoup.parse(h), "fixed");

        for (int iter=0; iter<10000; iter++) {
            StringBuilder sb = new StringBuilder();
            int roots = rnd.nextInt(3)+1;
            for (int i=0;i<roots;i++) build(sb, "body", 0);
            Document doc = Jsoup.parse(sb.toString());
            check(doc, "fuzz" + iter);
        }
        for (String s : samples) System.out.println(s);
        System.out.println("checked=" + checked + " fails=" + fails + " inDoc=" + inDocFails + " rt=" + rtFails + " det=" + detFails);
        if (fails>0) System.exit(1);
    }
}
