import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;

public class Chars {
    static int fails = 0;
    public static void main(String[] args) {
        for (int cp = 1; cp <= 0x2FF; cp++) {
            String ch = new String(Character.toChars(cp));
            if (ch.equals("'")) continue;
            idTest(ch, false);
            idTest(ch, true);   // leading position
            classTest(ch, false);
            classTest(ch, true);
            tagTest(ch, false);
            tagTest(ch, true);
        }
        System.out.println("FAILS=" + fails);
    }
    static void report(String kind, String ch, String sel, Object detail) {
        fails++;
        if (fails <= 80)
            System.out.println(kind + " cp=" + ch.codePointAt(0) + " (" + ch.replace("\n","\\n").replace("\r","\\r").replace("\t","\\t") + ") sel=[" + (sel==null?"":sel.replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")) + "] " + detail);
    }
    static void idTest(String ch, boolean leading) {
        Document doc = Document.createShell("");
        String v = leading ? ch + "z" : "z" + ch;
        Element a = doc.body().appendElement("div").id(v);
        Element b = doc.body().appendElement("div").id(v);
        for (Element el : new Element[]{a,b}) run("ID"+(leading?"L":"M"), ch, el, doc);
    }
    static void classTest(String ch, boolean leading) {
        Document doc = Document.createShell("");
        String cls = leading ? ch + "z" : "z" + ch;
        Element a = doc.body().appendElement("div").addClass(cls);
        Element b = doc.body().appendElement("div").addClass(cls);
        for (Element el : new Element[]{a,b}) run("CLS"+(leading?"L":"M"), ch, el, doc);
    }
    static void tagTest(String ch, boolean leading) {
        String tag = leading ? ch + "z" : "z" + ch;
        Document doc = Document.createShell("");
        Element a, b;
        try {
            a = doc.body().appendElement(tag);
            b = doc.body().appendElement(tag);
        } catch (Exception e) { return; }
        for (Element el : new Element[]{a,b}) run("TAG"+(leading?"L":"M"), ch, el, doc);
    }
    static void run(String kind, String ch, Element el, Document doc) {
        String s;
        try { s = el.cssSelector(); } catch (Exception e) { report(kind, ch, null, "cssSelector threw " + e); return; }
        try {
            Elements found = doc.select(s);
            if (found.size()!=1 || found.first()!=el) report(kind, ch, s, "matched="+found.size());
        } catch (Exception e) { report(kind, ch, s, "select threw " + e.getMessage()); }
    }
}
