private String cssSelectorComponent() {
    boolean rootLevel = parent() == null || parent() instanceof Document; // don't add Document to selector, as will always have a html node

    // Build the natural type+classes component. It is only usable if it reparses and matches this element within
    // its parent: some tag names (leading digit/hyphen, or a literal '|') cannot be expressed as a CSS type
    // selector, and an over-broad or otherwise non-matching component would fail to uniquely locate this element.
    String typeSelector = cssTypeSelector();
    StringBuilder selector = StringUtil.borrowBuilder().append(typeSelector);
    String classes = classNames().stream().map(TokenQueue::escapeCssIdentifier)
            .collect(StringUtil.joining("."));
    if (!classes.isEmpty())
        selector.append('.').append(classes);
    String component = StringUtil.releaseBuilder(selector);

    if (!cssComponentMatches(component, rootLevel))
        return cssStructuralComponent(rootLevel); // fall back to a universally expressible structural position

    if (rootLevel)
        return component;

    selector = StringUtil.borrowBuilder().append(" > ").append(component);
    if (parent().select(selector.toString()).size() > 1)
        selector.append(String.format(
            ":nth-child(%d)", elementSiblingIndex() + 1));

    return StringUtil.releaseBuilder(selector);
}

/**
 Escape this element's tag name as a CSS type selector, translating an HTML namespace {@code ns:tag} to the CSS
 namespace syntax {@code ns|tag}.
 */
private String cssTypeSelector() {
    return escapeCssIdentifier(tagName()).replace("\\:", "|");
}

/**
 Test whether the given type+classes component (without any combinator or nth-child suffix) both parses as a CSS
 selector and matches this element. Matching is scoped to this element's parent, or to the element itself when it
 has no element parent, so that the check is independent of the rest of the path being built.
 */
private boolean cssComponentMatches(String component, boolean rootLevel) {
    final Evaluator evaluator;
    try {
        evaluator = QueryParser.parse(component);
    } catch (Selector.SelectorParseException e) {
        return false;
    }
    Element scope = rootLevel ? this : parent();
    return evaluator.matches(scope, this);
}

